import pandas as pd
import numpy as np

class TrendFollowingStrategy:
    def __init__(self, data):
        self.data = data
        self.rsi_period = 14
        self.ichimoku_conversion_line_period = 9
        self.ichimoku_base_line_period = 26
        self.ichimoku_leading_span_period = 52
        self.ichimoku_lagging_span_period = 26
        self.stop_loss_trailing_percentage = 0.05
        self.position_sizing_percentage = 0.02

    def calculate_rsi(self):
        delta = self.data['Close'].diff()
        up, down = delta.copy(), delta.copy()
        up[up < 0] = 0
        down[down > 0] = 0
        roll_up = up.ewm(com=self.rsi_period - 1, adjust=False).mean()
        roll_down = down.ewm(com=self.rsi_period - 1, adjust=False).mean().abs()
        RS = roll_up / roll_down
        RSI = 100.0 - (100.0 / (1.0 + RS))
        return RSI

    def calculate_ichimoku(self):
        high = self.data['High']
        low = self.data['Low']
        conversion_line = (high.rolling(window=self.ichimoku_conversion_line_period).max() + low.rolling(window=self.ichimoku_conversion_line_period).min()) / 2
        base_line = (high.rolling(window=self.ichimoku_base_line_period).max() + low.rolling(window=self.ichimoku_base_line_period).min()) / 2
        leading_span = (conversion_line + base_line) / 2
        lagging_span = self.data['Close'].shift(-self.ichimoku_lagging_span_period)
        return conversion_line, base_line, leading_span, lagging_span

    def generate_signals(self):
        rsi = self.calculate_rsi()
        conversion_line, base_line, leading_span, lagging_span = self.calculate_ichimoku()
        signals = pd.DataFrame(index=self.data.index)
        signals['signal'] = 0
        signals.loc[(rsi < 30) & (self.data['Close'] > conversion_line) & (conversion_line > base_line), 'signal'] = 1
        signals.loc[(rsi > 70) & (self.data['Close'] < conversion_line) & (conversion_line < base_line), 'signal'] = -1
        return signals

    def calculate_stop_loss(self, signal):
        if signal == 1:
            stop_loss = self.data['Low'].rolling(window=10).min() * (1 - self.stop_loss_trailing_percentage)
        elif signal == -1:
            stop_loss = self.data['High'].rolling(window=10).max() * (1 + self.stop_loss_trailing_percentage)
        else:
            stop_loss = None
        return stop_loss

    def calculate_take_profit(self, signal):
        if signal == 1:
            take_profit = self.data['High'].rolling(window=10).max() * (1 + self.stop_loss_trailing_percentage)
        elif signal == -1:
            take_profit = self.data['Low'].rolling(window=10).min() * (1 - self.stop_loss_trailing_percentage)
        else:
            take_profit = None
        return take_profit

    def execute_strategy(self):
        signals = self.generate_signals()
        stop_loss = signals.apply(self.calculate_stop_loss, axis=1)
        take_profit = signals.apply(self.calculate_take_profit, axis=1)
        positions = pd.DataFrame(index=self.data.index)
        positions['position'] = 0
        positions.loc[signals['signal'] == 1, 'position'] = self.position_sizing_percentage
        positions.loc[signals['signal'] == -1, 'position'] = -self.position_sizing_percentage
        return positions

